// server/lib/data.ts
var sensoji = new Map(
  poems_sensoji_default.poems.map((p) => [p.number, p])
);
var tw60 = new Map(poems_tw60_default.poems.map((p) => [p.number, p]));
var judgments = new Map(
  judgments_sensoji_default.map((j) => [j.number, j])
);
var categories = new Map(
  category_map_default.categories.map((c) => [c.id, c])
);
function getCategory(id) {
  return categories.get(id);
}
function getSensojiPoem(n) {
  return sensoji.get(n);
}
function getTw60Poem(n) {
  return tw60.get(n);
}
function getJudgment(n, item) {
  const j = judgments.get(n);
  if (!j) return void 0;
  const part = j.items[item];
  return part ? { text: part, isWhole: false } : { text: j.judgment_original, isWhole: true };
}

